USE vocab_estimator; CREATE TABLE IF NOT EXISTS validation_sample (id BIGINT AUTO_INCREMENT PRIMARY KEY, known_words TEXT, unknown_words TEXT, standard_estimate INT DEFAULT 0, algorithm_estimate INT DEFAULT 0, known_count INT DEFAULT 0, unknown_count INT DEFAULT 0, diff INT DEFAULT 0, absolute_error INT DEFAULT 0, relative_error DOUBLE DEFAULT 0, create_time DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_create_time (create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;